mkdir -p /tmp/analysis && cat > /tmp/analysis/castcheck.py <<'EOF'
import itertools, sys
from functools import lru_cache

# types as tuples
def INT(): return ('int',)
TOP = ('top',)
def AND(a,b): return ('and',a,b)
def RCD(n,a): return ('rcd',n,a)
def ARR(a,b): return ('arr',a,b)

def tsize(t):
    k=t[0]
    if k in ('int','top'): return 1
    if k=='and': return 1+tsize(t[1])+tsize(t[2])
    if k=='rcd': return 1+tsize(t[2])
    if k=='arr': return 1+tsize(t[1])+tsize(t[2])
    raise Exception(t)

MAXT=int(sys.argv[1]) if len(sys.argv)>1 else 5
IDX=[0,1]
types=set()
def gen_types():
    bysize={1:[INT(),TOP]}
    types.add(INT()); types.add(TOP)
    for s in range(2,MAXT+1):
        lst=[]
        for a,sa in list(by_size.items()):
            pass
    # simpler: enumerate recursively with memo
    from functools import lru_cache
    @lru_cache(None)
    def gen(s):
        res=set()
        if s==1: res|={INT(),TOP}
        for i in range(1,s-1):
            j=s-1-i
            if i>=1 and j>=1:
                for a in gen(i):
                    for b in gen(j):
                        res.add(AND(a,b)); res.add(ARR(a,b))
                for a in gen(j):
                    for n in IDX:
                        res.add(RCD(n,a))
        return frozenset(res)
    allt=set()
    for s in range(1,MAXT+1): allt|=set(gen(s))
    return sorted(allt,key=lambda t:(tsize(t),str(t)))
by_size={}
U=gen_types()
# ensure closures of subterms: U obtained by generation is closed
print("num types",len(U))

def sub_all(U):
    S=set()
    changed=True
    while changed:
        changed=False
        for A in U:
            if (A,TOP) not in S: S.add((A,TOP)); changed=True
        if (INT(),INT()) not in S: S.add((INT(),INT())); changed=True
        # sand, sandl, sandr, srcd, sarr — iterate over U
        for A in U:
            for B in U:
                if (A,B) in S:
                    for C in U:
                        if C[0]=='and' and (A,C) not in S:
                            pass
        # do full naive closure
        n=len(S)
        new=set(S)
        for A in U:
            for B in U:
                for C in U:
                    if (A,B) in S and C[0]=='and' and (A,C) not in new:
                        new.add((A,C))
                    if (B,C) in S and A[0]=='and' and (A,C) not in new:
                        new.add((A,C))
                    if (A,B) in S and B[0]=='and':
                        pass
        # sand: if sub A B and sub A C then sub A (and B C)
        for A in U:
            for B in U:
                if (A,B) in S:
                    for C in U:
                        if (A,C) in S and (A,AND(B,C)) not in new:
                            new.add((A,AND(B,C)))
                    # sandl: A=and? handled below
                if A[0]=='and':
                    for C in U:
                        if (A[1],C) in S and (A,C) not in new: new.add((A,C))
                        if (A[2],C) in S and (A,C) not in new: new.add((A,C))
                # srcd
                if A[0]=='rcd' and B[0]=='rcd' and A[1]==B[1] and (A[2],B[2]) in S and (A,B) not in new:
                    new.add((A,B))
                # sarr
                if A[0]=='arr' and B[0]=='arr' and (B[1],A[1]) in S and (A[2],B[2]) in S and (A,B) not in new:
                    new.add((A,B))
        if new!=S: changed=True; S=new
    return S

SUB=sub_all(U)
print("sub size",len(SUB))

def gord(t):
    k=t[0]
    if k=='int': return True
    if k=='arr': return gord(t[2])
    if k=='rcd': return gord(t[2])
    return False
def ord(t):
    return t[0] in ('int','arr','rcd')
def toplike(t):
    k=t[0]
    if k=='top': return True
    if k=='and': return toplike(t[1]) and toplike(t[2])
    if k=='arr': return toplike(t[2])
    if k=='rcd': return toplike(t[2])
    return False
def cost_spec(A,B):
    for C in U:
        if gord(C) and (A,C) in SUB and (B,C) in SUB: return C
    return None
def disjoint(A,B): return cost_spec(A,B) is None
print("cost_spec samples ok")

# terms as tuples
def lit(i): return ('lit',i)
UNIT=('unit',)
def M(a,b): return ('mrg',a,b)
def REC(n,a): return ('rec',n,a)
def ANN(e,t): return ('ann',e,t)
def LAM(fm,e): return ('lam',fm,e)
def BOX(a,b): return ('box',a,b)
LITS=[lit(i) for i in range(3)]
FMS=['bl','wh']

def esize(e):
    k=e[0]
    if k in ('lit','unit','ctx'): return 1
    if k=='mrg': return 1+esize(e[1])+esize(e[2])
    if k=='rec': return 1+esize(e[2])
    if k=='ann': return 1+esize(e[1])+tsize(e[2])
    if k=='lam': return 1+esize(e[2])
    if k=='box': return 1+esize(e[1])+esize(e[2])
    return 1

MAXE=int(sys.argv[2]) if len(sys.argv)>2 else 6

# enumerate values: lit, unit, mrg, rec, box with closure annotation arr A B
vals=set()
def gen_vals(maxsz):
    # iteratively by size
    res=set()
    for s in range(1,maxsz+1):
        cur=set()
        if s==1: cur|={lit(0),lit(1),lit(2),UNIT}
        for i in range(1,s-1):
            j=s-1-i
            if i>=1 and j>=1:
                for a in res_or(cur,i) if False else []:
                    pass
        # do proper recursive generation by size using all smaller sizes
        # merge
        for si in range(1,s-1):
            sj=s-1-si
            if si>=1 and sj>=1:
                for a in by_vals.get(si,set()):
                    for b in by_vals.get(sj,set()):
                        cur.add(M(a,b))
        # rec
        if s>=2:
            for a in by_vals.get(s-1,set()):
                cur.add(REC(0,a))
        # box closure: box v (ann (lam fm e) (arr A B)) size = 1 + size v + (1+size e + size typ)
        # parameterize by annotation type arr A B and body e
        for sv in range(1,s-1):
            rest=s-1-sv
            # rest = size of ann = 1+size e+ size(arr A B) ; need size(arr A B)>=2 => rest>=3
            for at in U:
                if at[0]!='arr': continue
                for fm in FMS:
                    # choose body e among small typable-ish terms; use lit 0/unit/box unit ann
                    for ebody in [lit(0), lit(1), UNIT]:
                        if 1+esize(ebody)+tsize(at)==rest+1-1+0 or True:
                            ann=ANN(LAM(fm,ebody),at)
                            if esize(ann)+sv+1==s:
                                for v in by_vals.get(sv,set()):
                                    cur.add(BOX(v,ann))
        # also box with first comp bigger handled above
        by_vals[s]=cur
        res|=cur
    return res
by_vals={}
gen_vals(MAXE)
vals=set()
for s in by_vals: vals|=by_vals[s]
print("num values",len(vals))

def is_value(e):
    k=e[0]
    if k=='lit' or k=='unit': return True
    if k=='mrg': return is_value(e[1]) and is_value(e[2])
    if k=='rec': return is_value(e[2])
    if k=='box':
        return is_value(e[1]) and e[2][0]=='ann' and e[2][1][0]=='lam' and e[2][2][0]=='arr'
    return False
vals={v for v in vals if is_value(v)}
print("num real values",len(vals))

# genv
def genv_terms():
    res=set()
    changed=True
    while changed:
        changed=False
        if (TOP,UNIT) not in res: res.add((TOP,UNIT)); changed=True
        for (A,v) in list(res):
            # arr
            for B in U:
                t=ARR(A,B)
                nv=BOX(UNIT,ANN(LAM('bl',v),t))
                if (t,nv) not in res: res.add((t,nv)); changed=True
            for l in IDX:
                t=RCD(l,A)
                nv=REC(l,v)
                if (t,nv) not in res: res.add((t,nv)); changed=True
        for (A,v1) in list(res):
            for (B,v2) in list(res):
                t=AND(A,B); nv=M(v1,v2)
                if (t,nv) not in res: res.add((t,nv)); changed=True
    return res
GENV=genv_terms()
print("genv size",len(GENV))
genv_rel=set(GENV)
def genv(A,v): return (A,v) in genv_rel

# ext
EXT=set()
for A in U:
    EXT.add((A,'bl',A))
    if A[0]=='rcd': EXT.add((A,'wh',A[2]))
def ext(A,fm,X): return (A,fm,X) in EXT

# casting fixpoint: set of (v,X,v')
CAST=set()
def close_casting():
    global CAST
    changed=True
    it=0
    while changed:
        changed=False; it+=1
        new=set()
        for v in vals:
            # cast_top
            new.add((v,TOP,UNIT))
            if v[0]=='lit':
                new.add((v,INT(),v))
            if v[0]=='mrg':
                a,b=v[1],v[2]
                for X in U:
                    if ord(X):
                        for (vv,XX,vv2) in CAS('a') if False else []:
                            pass
        # structured
        # mrgl/mrgr
        for v in vals:
            if v[0]=='mrg':
                a,b=v[1],v[2]
                for X in U:
                    if ord(X):
                        for w in vals:
                            if (a,X,w) in CAST and (v,X,w) not in new: new.add((v,X,w))
                            if (b,X,w) in CAST and (v,X,w) not in new: new.add((v,X,w))
            if v[0]=='rec':
                w=v[2]; n=v[1]
                for X0 in U:
                    for w2 in vals:
                        if (w,X0,w2) in CAST and (v,RCD(n,X0),REC(n,w2)) not in new:
                            new.add((v,RCD(n,X0),REC(n,w2)))
            if v[0]=='box':
                vv=v[1]; ann=v[2]
                if ann[0]=='ann' and ann[1][0]=='lam' and ann[2][0]=='arr':
                    fm=ann[1][1]; ebody=ann[1][2]; Aa=ann[2][1]; Ba=ann[2][2]
                    for X in U:
                        if X[0]=='arr':
                            C,D=X[1],X[2]
                            for Aext in U:
                                if ext(Aa,fm,Aext) and (C,Aext) in SUB and (Ba,D) in SUB:
                                    if not toplike(D):
                                        r=BOX(vv,ANN(LAM(fm,ebody),ARR(Aa,D)))
                                        if (v,X,r) not in new: new.add((v,X,r))
                                    if toplike(D):
                                        gv=[g for (T,g) in GENV if T==X]
                                        if gv:
                                            r=gv[0]
                                            if (v,X,r) not in new: new.add((v,X,r))
            # cast_and
            for X in U:
                if X[0]=='and':
                    A,B=X[1],X[2]
                    for w1 in vals:
                        if (v,A,w1) in CAST:
                            for w2 in vals:
                                if (v,B,w2) in CAST:
                                    r=M(w1,w2)
                                    if (v,X,r) not in new: new.add((v,X,r))
        if new!=CAST:
            changed=True; CAST=new
    return CAST
CAST=close_casting()
print("cast size",len(CAST))

# inf types overapprox
def inf_types(e):
    if e[0]=='lit': return {INT()}
    if e[0]=='unit': return {TOP}
    if e[0]=='rec':
        return {RCD(e[1],A) for A in inf_types(e[2])}
    if e[0]=='mrg':
        res=set()
        for A in inf_types(e[1]):
            for B in inf_types(e[2]):
                res.add(AND(A,B))
        return res
    if e[0]=='box':
        ann=e[2]
        if ann[0]=='ann' and ann[1][0]=='lam' and ann[2][0]=='arr':
            return {ann[2]}
    return set()

# check L2
print("checking L2 (disjoint values cast differently at ord X)...")
cnt=0
badex=[]
val_list=sorted(vals,key=lambda e:esize(e))
for a in val_list:
    Ats=inf_types(a)
    for A in Ats:
        for b in val_list:
            if esize(a)+esize(b)>MAXE+1: continue
            Bts=inf_types(b)
            for B in Bts:
                if not disjoint(A,B): continue
                for X in U:
                    if not ord(X): continue
                    wa=[w for (v,XX,w) in CAST if v==a and XX==X]
                    wb=[w for (v,XX,w) in CAST if v==b and XX==X]
                    for va in wa:
                        for vb in wb:
                            if va!=vb:
                                badex.append((a,A,b,B,X,va,vb))
                                if len(badex)<5: print("BAD",a,A,b,B,X,va,vb)
    cnt+=1
print("L2 counterexamples:",len(badex))
